#pragma once

#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <string>
#include <vector>

#include "kr32/container/container.h"

namespace kr32::os {

// Loads the sibling <kernel>.sym sidecar generated by `kr32 ld --flat --sym`.
// Returns false with an empty error when no sidecar exists.
inline bool load_symbol_file(const std::string& kernel_path,
                             const std::vector<std::uint8_t>& kernel,
                             container::Image& image,
                             std::string& error) {
    error.clear();
    std::filesystem::path path(kernel_path);
    path.replace_extension(".sym");
    if (!std::filesystem::exists(path)) {
        return false;
    }
    std::ifstream input(path, std::ios::binary);
    if (!input) {
        error = "cannot read " + path.string();
        return false;
    }
    std::vector<std::uint8_t> bytes(
        (std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
    container::Error container_error;
    if (!container::read(bytes, image, container_error)) {
        error = "invalid symbol sidecar: " + container_error.message;
        return false;
    }
    std::uint32_t expected = 0;
    for (const container::Section& section : image.sections) {
        if (section.name != "__sym_crc" || section.data.size() != 4) {
            continue;
        }
        expected = static_cast<std::uint32_t>(section.data[0]) |
                   (static_cast<std::uint32_t>(section.data[1]) << 8U) |
                   (static_cast<std::uint32_t>(section.data[2]) << 16U) |
                   (static_cast<std::uint32_t>(section.data[3]) << 24U);
        break;
    }
    if (expected == 0) {
        error = "symbol sidecar has no image checksum";
        return false;
    }
    if (expected != container::crc32(kernel.data(), kernel.size())) {
        error = "symbol sidecar does not match the kernel image";
        return false;
    }
    return true;
}

} // namespace kr32::os
